import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CmvPqeTF.js";const u=JSON.parse('{"title":"服务器监控","description":"","frontmatter":{},"headers":[],"relativePath":"guide/monitor.md","filePath":"guide/monitor.md","lastUpdated":1788361893000}'),o={name:"guide/monitor.md"};function i(s,t,c,l,h,n){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="服务器监控" tabindex="-1">服务器监控 <a class="header-anchor" href="#服务器监控" aria-label="Permalink to &quot;服务器监控&quot;">​</a></h1><p>ActivityBar 底部的活动图表图标打开监控面板（底部区域）。连接建立后<strong>自动开始采集</strong>，断开时自动停止——复用 SSH 连接，无需重复认证，也不在服务器上安装任何代理。</p><hr><h2 id="_1-采集范围与频率" tabindex="-1">1. 采集范围与频率 <a class="header-anchor" href="#_1-采集范围与频率" aria-label="Permalink to &quot;1. 采集范围与频率&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>采集间隔</th><th>数据源（远端命令）</th></tr></thead><tbody><tr><td>CPU / 内存 / 网络 / 在线时长</td><td>2s</td><td><code>/proc/stat</code>、<code>/proc/meminfo</code>、<code>/proc/net/dev</code>、<code>/proc/uptime</code></td></tr><tr><td>负载</td><td>5s</td><td><code>/proc/loadavg</code></td></tr><tr><td>进程</td><td>5s</td><td>`ps -eo pid,user,%cpu,%mem,rss,args --sort=-%cpu</td></tr><tr><td>磁盘</td><td>10s</td><td><code>df -B1 -x tmpfs -x devtmpfs</code></td></tr><tr><td>监听端口 / 连接</td><td>10s</td><td><code>ss -tlnp</code>、<code>ss -tnp state established</code></td></tr></tbody></table><p>面板切换的是<strong>当前激活终端标签</strong>所属连接的监控数据；无活动连接时提示「无活动连接」。</p><h2 id="_2-概览栏-左侧-280px" tabindex="-1">2. 概览栏（左侧 280px） <a class="header-anchor" href="#_2-概览栏-左侧-280px" aria-label="Permalink to &quot;2. 概览栏（左侧 280px）&quot;">​</a></h2><p>自上而下：</p><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>主机</td><td>主机名 + 系统类型 + IP 列表（排除 127.0.0.1）</td></tr><tr><td>在线时长</td><td><code>d h m</code> 格式</td></tr><tr><td>CPU</td><td>总占用进度条</td></tr><tr><td>内存</td><td>已用 / 总量</td></tr><tr><td>进程 TOP5</td><td>名称 + CPU% + 内存%</td></tr><tr><td>磁盘</td><td>挂载点汇总</td></tr><tr><td>网络</td><td>↓ 接收 / ↑ 发送速率</td></tr></tbody></table><p><strong>每项都可点击</strong>，右侧详情区随之切换。</p><h2 id="_3-详情区" tabindex="-1">3. 详情区 <a class="header-anchor" href="#_3-详情区" aria-label="Permalink to &quot;3. 详情区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>详情</th><th>内容</th></tr></thead><tbody><tr><td>CPU</td><td>每核心独立进度条</td></tr><tr><td>内存</td><td>物理内存 + 交换区（无 swap 显示「无交换区」）</td></tr><tr><td>磁盘</td><td>每个挂载点：百分比、设备、已用 / 总量</td></tr><tr><td>进程</td><td>完整表格（PID、CPU、内存、用户、命令、路径），列可排序，命令与路径可一键复制</td></tr><tr><td>网络</td><td>二级标签「网卡 / 进程」</td></tr></tbody></table><h3 id="网络详情" tabindex="-1">网络详情 <a class="header-anchor" href="#网络详情" aria-label="Permalink to &quot;网络详情&quot;">​</a></h3><ul><li><strong>网卡页</strong>：顶部 <strong>ECharts 趋势折线图</strong>（↓RX 蓝 / ↑TX 橙，约 60 个采样点窗口），下方接口表（接收 / 发送速率与累计流量），点击某行切换图表对象</li><li><strong>进程页</strong>：监听进程表（PID、进程、监听地址、端口、连接数）</li></ul><h2 id="_4-显示约定" tabindex="-1">4. 显示约定 <a class="header-anchor" href="#_4-显示约定" aria-label="Permalink to &quot;4. 显示约定&quot;">​</a></h2><p>百分比进度条颜色阈值：&lt; 60% 绿色、&lt; 85% 黄色、≥ 85% 红色。</p><h2 id="_5-实现说明" tabindex="-1">5. 实现说明 <a class="header-anchor" href="#_5-实现说明" aria-label="Permalink to &quot;5. 实现说明&quot;">​</a></h2><ul><li>采集通过在既有 SSH 连接上周期性 exec 命令完成（每轮新建 exec 会话），<strong>数据不落库</strong>，面板关闭只是不显示、采集随连接生命周期</li><li>CPU 百分比按 <code>/proc/stat</code> 两次采样差值计算（含逐核）；网卡速率按相邻两次 <code>/proc/net/dev</code> 差值 ÷ 间隔计算</li><li>监控指标目前仅支持 Linux（<code>/proc</code>、<code>df</code>、<code>ss</code>）；非 Linux 系统仅显示主机名等基础信息</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../dev/architecture.html">架构总览</a> —— Monitor 与 SSH 连接复用的关系</li></ul>',21)])])}const b=d(o,[["render",i]]);export{u as __pageData,b as default};
